// This code generates a random integer between a specified minimum and maximum value (inclusive).
// It is structured to return a standard n8n item object.

// Define the range (inclusive)
const MIN = Math.floor(Math.random() * (31 - 20 + 1)) + 20;
const MAX = Math.floor(Math.random() * (41 - 32 + 1)) + 32;

/**
 * Generates a truly random integer between min and max, inclusive.
 */
function getRandomIntInclusive(min, max) {
  // Ensure min and max are integers
  min = Math.ceil(min);
  max = Math.floor(max);
  // The maximum is inclusive and the minimum is inclusive
  return Math.floor(Math.random() * (max - min + 1)) + min;
}

// Generate the random number
const randomNumber = getRandomIntInclusive(MIN, MAX);

// Output the result in the standard n8n format: an array of items.
// The next node can access this value using the expression: {{ $json.randomNumber }}
return [{ json: { randomNumber: randomNumber } }];
